function addrealtimeCart(){

    var currency = $('#currency').val()

    var get_local_cart_item = localStorage.getItem('jStorage')
    var access_to_item = JSON.parse(get_local_cart_item)
    var obj_json  = access_to_item['cesta-feira-items']
  
    if(Object.keys(obj_json).length > 0){
      $('.side-panel-content').html('')
      for(let i of Object.keys(obj_json)){

        if (obj_json[i]['order_type'] === 'Customize'){
          var edit_link = ""
        }else{
          var edit_link = "<a class='' href='/product/"+ i +"'><i class='fa fa-edit'></i> Edit</a>"
        }

        var totalValueTemp = parseFloat(obj_json[i]['unity_price']) * parseInt(obj_json[i]['quantity']);
        var $layout ="<div class='basket-product' id='cart_items_main_div"+i+"'>"+
        "<div class='item'>"+
        "<div class='product-image'>"+
        "<img class='product-frame' height='78px' src='"+obj_json[i]['item_type']+"' alt='"+ obj_json[i]['product_name'] +"'>"+
        "</div>"+
        "<div class='product-details'>"+
        "<div class='product_name_del'>"+
          "<div class='product_vari'>"+
            "<h1 class='head'><strong><span class='item-quantity'>" + obj_json[i]['quantity'] +"</span> x " + obj_json[i]['product_brand'] +" </strong>"+ obj_json[i]['product_name'].slice(0,30) +"..</h1>"+
            "<p><span class='"+ obj_json[i]['size'] +"'> Size :"+ obj_json[i]['size'] +" </span>  <span class='"+ obj_json[i]['color'] +"'> , Color :"+ obj_json[i]['color'] +" </span> </p>"+
            "<p>Product Code - "+ obj_json[i]['id'] +"</p>"+
          "</div>"+
          "<div class='remove'>"+
            "<a href='javascript:;' class='btn text-danger fa fa-trash cart_item_del_btn' data-del_item='#cart_items_main_div"+i+"' data-cesta-feira-delete-item='"+ i +"'><span class='sr-only'>Remove</span></a>"+         
          "</div>"+

        "</div>"+

        "<div class='price_and_qty_and_total'>"+
          "<div class='price'>"+currency+""+ obj_json[i]['unity_price'] +"</div>"+
          "<div class='item_quantity'>"+
          "<div class='item-qty'>Qty. " + obj_json[i]['quantity'] +"</div>"+
          ""+edit_link+""+
          "</div>"+
          "<div class='subtotal' data-item-total-value='"+totalValueTemp+"'>"+currency+""+parseFloat(totalValueTemp)+"</div>"+
        "</div>"+

        "</div>"+
        "</div>"+
     
        "</div>";


        
        $('.side-panel-content').append($layout)



        




        
        
    }
    
     var show_btn =  `<div class='side_action_btn_parent'>
        <div class="cart_link_in_side">
        <a href='/cart/'>View Cart</a>
        </div>

        <div class="cart_link_in_side checkbtn_color">
            <a href='/checkout/'>
            checkout
            </a>
            </div>
        </div>`

      $(".side-panel-action-btn").html(show_btn)
      $('#Cart-Drawer').css({'transform':'translateX(0%)'})
      $(".blur_shadow_bg").css({'display':'block'})
  
  
  
    }else{
        var mystr = `
        <div class="cart-drawer__empty-cart">
          <img src="/static/shop/img/cart-plus.svg" alt="cart-svg">
          <p>Your cart is currently empty.</p>
          <a class="button accent2" href="/"><span>Start Shopping</span></a>
        </div>
        `;
        $(".side-panel-content").html(mystr);

        $('.side-panel-action-btn').html('')
  
    }
  
  }
